    // Transferring zero or negative amounts between accounts
    @Test
    public void test_transfer_zero_or_negative_amount() {
        // Arrange
        Bank bank = new Bank();
        Account account1 = new Account("123456", "John Doe", 1000.0);
        Account account2 = new Account("654321", "Jane Doe", 500.0);
        bank.addAccount(account1);
        bank.addAccount(account2);

        // Act & Assert
        Exception exceptionZero = assertThrows(IllegalArgumentException.class, () -> {
            bank.transfer("123456", "654321", 0);
        });
        assertEquals("Withdrawal amount must be positive.", exceptionZero.getMessage());

        Exception exceptionNegative = assertThrows(IllegalArgumentException.class, () -> {
            bank.transfer("123456", "654321", -100);
        });
        assertEquals("Withdrawal amount must be positive.", exceptionNegative.getMessage());

        // Ensure balances remain unchanged
        assertEquals(1000.0, account1.getBalance());
        assertEquals(500.0, account2.getBalance());
    }

