    // Concurrent access to bank operations
    @Test
    public void test_concurrent_transfers() throws InterruptedException {
        // Arrange
        Bank bank = new Bank();
        Account account1 = new Account("123456", "John Doe", 1000.0);
        Account account2 = new Account("654321", "Jane Doe", 1000.0);
        bank.addAccount(account1);
        bank.addAccount(account2);

        // Act
        Thread thread1 = new Thread(() -> {
            try {
                bank.transfer("123456", "654321", 100.0);
            } catch (Exception e) {
                e.printStackTrace();
            }
        });

        Thread thread2 = new Thread(() -> {
            try {
                bank.transfer("654321", "123456", 200.0);
            } catch (Exception e) {
                e.printStackTrace();
            }
        });

        thread1.start();
        thread2.start();

        thread1.join();
        thread2.join();

        // Assert
        assertEquals(2000.0, account1.getBalance() + account2.getBalance());
    }

    // Transaction isolation between multiple transfers
    @Test
    public void test_transaction_isolation_between_multiple_transfers() throws Exception {
        // Arrange
        Bank bank = new Bank();
        Account account1 = new Account("123456", "John Doe", 1000.0);
        Account account2 = new Account("654321", "Jane Doe", 500.0);
        Account account3 = new Account("111111", "Jim Beam", 300.0);
        bank.addAccount(account1);
        bank.addAccount(account2);
        bank.addAccount(account3);

        // Act & Assert
        assertTrue(bank.transfer("123456", "654321", 200.0));
        assertEquals(800.0, account1.getBalance());
        assertEquals(700.0, account2.getBalance());

        assertTrue(bank.transfer("654321", "111111", 100.0));
        assertEquals(600.0, account2.getBalance());
        assertEquals(400.0, account3.getBalance());

        // Ensure isolation: previous transfers should not affect this one
        assertTrue(bank.transfer("123456", "111111", 300.0));
        assertEquals(500.0, account1.getBalance());
        assertEquals(700.0, account3.getBalance());
    }

